/**
 * `shutro generate` over the RFC 0002 §7.9 fixture graph. The generated files under `test/fixtures/**\/.shutro` are
 * committed goldens: the first test fails when they drift. Regenerate with `UPDATE_GOLDENS=1 pnpm vitest run packages/cli`.
 */
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, describe, expect, test } from 'vitest';
import {
  ConfigError,
  generate,
  interfaceName,
  loadConfig,
  ModuleSourceError,
} from '../src/index.js';

const fixtures = join(import.meta.dirname, 'fixtures');
const configFile = join(fixtures, 'shutro.config.ts');
const scratch = mkdtempSync(join(tmpdir(), 'shutro-generate-'));

afterAll(() => {
  rmSync(scratch, { recursive: true, force: true });
});

describe('generate', () => {
  test('the committed views are current (5 modules × 2 files + the application view)', async () => {
    const { config, dir } = await loadConfig(configFile);
    const update = process.env['UPDATE_GOLDENS'] === '1';
    const result = await generate({ config, cwd: dir, check: !update });
    expect(result.modules).toEqual(['base', 'sale', 'sale_margin', 'stock', 'sale_stock']);
    expect(result.files).toHaveLength(12);
    if (!update) expect(result.changed.map((f) => f.path)).toEqual([]);
  });

  test('writes into outRoot: created, then unchanged, then updated after tampering', async () => {
    const { config, dir } = await loadConfig(configFile);
    const first = await generate({ config, cwd: dir, outRoot: scratch });
    expect(new Set(first.files.map((f) => f.status))).toEqual(new Set(['created']));
    const second = await generate({ config, cwd: dir, outRoot: scratch });
    expect(second.changed).toEqual([]);
    const target = second.files.find((f) =>
      f.path.endsWith(join('sale', '.shutro', 'schema.d.ts')),
    );
    expect(target).toBeDefined();
    if (target === undefined) return;
    // Identical to the committed golden: the output doesn't depend on where it is written.
    expect(target.content).toBe(
      readFileSync(join(fixtures, 'sale', '.shutro', 'schema.d.ts'), 'utf8'),
    );
    writeFileSync(target.path, '// edited\n');
    const checked = await generate({ config, cwd: dir, outRoot: scratch, check: true });
    expect(checked.changed.map((f) => f.status)).toEqual(['updated']);
    expect(readFileSync(target.path, 'utf8')).toBe('// edited\n'); // check writes nothing
    const third = await generate({ config, cwd: dir, outRoot: scratch });
    expect(third.changed.map((f) => f.status)).toEqual(['updated']);
    expect(readFileSync(target.path, 'utf8')).toBe(target.content);
  });

  test('each module view contains only what the module can see (RFC 0002 §7.9)', () => {
    const view = (module: string): string =>
      readFileSync(join(fixtures, module, '.shutro', 'schema.d.ts'), 'utf8');
    const sale = view('sale');
    expect(sale).toMatch(
      /^\/\/ GENERATED by `shutro generate`\. Do not edit\. definitions-hash: [0-9a-f]{16}\n/,
    );
    expect(sale).toContain("readonly 'sale.order': SaleOrder;");
    expect(sale).toContain(
      "readonly partner: F.Many2one<'res.partner', { readonly required: true }>;",
    );
    expect(sale).toContain(
      "readonly amountTotal: F.Monetary<'currency', { readonly readonly: true; readonly compute: 'computeAmounts'; readonly store: true }>;",
    );
    expect(sale).toContain(
      "readonly state: F.Selection<'draft' | 'sale' | 'cancel', { readonly default: true }>;",
    );
    expect(sale).toContain("readonly id: F.Id<'sale.order'>;");
    expect(sale).not.toContain('warehouse');
    expect(sale).not.toContain('margin');
    expect(sale).not.toContain('stock.warehouse');

    const saleStock = view('sale_stock');
    expect(saleStock).toContain(
      "readonly warehouse: F.Many2one<'stock.warehouse', { readonly required: true; readonly default: true }>; // sale_stock",
    );
    expect(saleStock).toContain("readonly 'stock.warehouse': StockWarehouse;");
    expect(saleStock).toContain(
      "F.Methods<typeof import('../../sale/module.js').sale, 'sale.order'>, F.Methods<typeof import('../module.js').saleStock, 'sale.order'>",
    );
    expect(saleStock).not.toContain('margin');

    const app = readFileSync(join(fixtures, 'app', '.shutro', 'schema.d.ts'), 'utf8');
    expect(app).toContain('readonly warehouse:');
    expect(app).toContain(
      "readonly margin: F.Decimal<{ readonly readonly: true; readonly compute: 'computeMargin'; readonly store: true }>; // sale_margin",
    );
    expect(app).toContain('(owner: sale; extended by: sale_margin, sale_stock)');
  });

  test('a dependency that is not listed is an error naming the module that needs it', async () => {
    const { config, dir } = await loadConfig(configFile);
    const partial = {
      modules: config.modules.filter(
        (m) => !m.endsWith(join('stock', 'module.ts')) || m.includes('sale_stock'),
      ),
    };
    await expect(generate({ config: partial, cwd: dir, check: true })).rejects.toThrow(
      ModuleSourceError,
    );
    await expect(generate({ config: partial, cwd: dir, check: true })).rejects.toThrow(
      /'stock' \(a dependency of 'sale_stock'\)/,
    );
  });

  test('a listed file must export exactly one module', async () => {
    await expect(
      generate({ config: { modules: [configFile] }, cwd: fixtures, check: true }),
    ).rejects.toThrow(ConfigError);
    await expect(
      generate({ config: { modules: [join(fixtures, 'nope.ts')] }, cwd: fixtures, check: true }),
    ).rejects.toThrow(/does not exist/);
  });

  test('interface names', () => {
    expect(interfaceName('sale.order.line')).toBe('SaleOrderLine');
    expect(interfaceName('res_partner.bank')).toBe('ResPartnerBank');
  });
});

describe('loadConfig', () => {
  test('resolves paths against the config file', async () => {
    const { config, dir } = await loadConfig(configFile);
    expect(dir).toBe(fixtures);
    expect(config.modules[0]).toBe(join(fixtures, 'base', 'module.ts'));
    expect(config.app).toBe(join(fixtures, 'app'));
  });

  test('missing or malformed config files are typed errors', async () => {
    await expect(loadConfig(join(fixtures, 'missing.config.ts'))).rejects.toThrow(ConfigError);
    await expect(loadConfig(join(fixtures, 'base', 'module.ts'))).rejects.toThrow(
      /does not export a config/,
    );
  });
});
